def get_count(self, using):
    """
    Perform a COUNT() query using the current filter constraints.
    """
    obj = self.clone()
    # Annotations don't change the number of rows, so they can be dropped
    # unless a filter (HAVING/QUALIFY) or GROUP BY over values() needs them.
    _, having, qualify = obj.where.split_having_qualify()
    # Joins only the removed annotations used must go too: a LEFT JOIN to
    # a multi-valued relation would otherwise multiply the rows. Subqueries
    # may reference those joins through OuterRef, so keep everything then.
    used, subquery = set(), False
    for leaf in obj.where.leaves():
        for expr in (leaf, getattr(leaf, "lhs", None), getattr(leaf, "rhs", None)):
            if isinstance(expr, Query):
                subquery = True
            for col in getattr(expr, "flatten", lambda: ())():
                if isinstance(col, Col):
                    used.add(col.alias)
                elif isinstance(getattr(col, "query", None), Query):
                    subquery = True
    if not (
        isinstance(obj.group_by, tuple)
        or having
        or qualify
        or subquery
        or obj.is_sliced
        or obj.distinct
        or obj.combinator
    ):
        keep = {obj.base_table}
        for alias in used:
            while alias and alias not in keep:
                keep.add(alias)
                alias = getattr(obj.alias_map.get(alias), "parent_alias", None)
        for alias in obj.alias_map:
            if alias not in keep:
                obj.alias_refcount[alias] = 0
        obj.annotations = {}
        obj.set_annotation_mask(None)
        obj.group_by = None
    obj.add_annotation(Count("*"), alias="__count", is_summary=True)
    return obj.get_aggregation(using, ["__count"])["__count"]

